//! read-only file permissions when a guest attempted to truncate a file.
//!
//! The host runs this program with a directory named `readonly` preopened using
//! read-only file permissions (`FilePerms::READ`). The directory contains a file
//! `test.txt` whose contents are exactly `b"truncation test file\n"`. Attempting
//! to open that file with the truncation flag must be rejected by the runtime,
//! and the file's contents must remain unchanged.

use test_programs::wasi;
use test_programs::wasi::filesystem::types::{DescriptorFlags, OpenFlags, PathFlags};

const FILENAME: &str = "test.txt";
const CONTENTS: &[u8] = b"truncation test file\n";

fn main() {
    let preopens = wasi::filesystem::preopens::get_directories();
    let dir = preopens
        .iter()
        .find(|(_, name)| name == "readonly")
        .map(|(dir, _)| dir)
        .expect("a preopened directory named `readonly`");

    // Attempt to open the file with the truncation flag. The directory was
    // preopened with read-only file permissions, so the runtime must reject
    // this rather than silently truncating the file.
    let result = dir.open_at(
        PathFlags::empty(),
        FILENAME,
        OpenFlags::TRUNCATE,
        DescriptorFlags::READ,
    );
    assert!(
        result.is_err(),
        "truncating a file in a read-only preopen must be rejected"
    );

    // Re-verify from within the guest that the file still contains its original
    // contents: the rejected truncation must not have modified anything.
    let file = dir
        .open_at(
            PathFlags::empty(),
            FILENAME,
            OpenFlags::empty(),
            DescriptorFlags::READ,
        )
        .expect("opening the file for reading");
    let stream = file.read_via_stream(0).unwrap();
    let mut contents = Vec::new();
    loop {
        match stream.blocking_read(128) {
            Ok(chunk) => contents.extend(chunk),
            Err(wasi::io::streams::StreamError::Closed) => break,
            Err(e) => panic!("failed reading file: {e:?}"),
        }
    }
    assert_eq!(
        contents, CONTENTS,
        "file contents must be unchanged after a rejected truncation"
    );
}
