//! read-only file permissions (`FilePerms::READ`). The directory contains a file
//! `test.txt` whose contents are exactly `b"truncation test file\n"`. Attempting
//! to open that file with the truncation flag must be rejected by the runtime,
//! and the file's contents must remain unchanged.

use test_programs::preview1::open_scratch_directory;

const FILENAME: &str = "test.txt";
const CONTENTS: &[u8] = b"truncation test file\n";

fn test_readonly_truncation(dir_fd: wasip1::Fd) {
    // Attempt to open the file for truncation. The directory was preopened with
    // read-only file permissions, so the runtime must reject this rather than
    // silently truncating the file.
    let result = unsafe {
        wasip1::path_open(
            dir_fd,
            0,
            FILENAME,
            wasip1::OFLAGS_TRUNC,
            wasip1::RIGHTS_FD_READ,
            0,
            0,
        )
    };
    assert!(
        result.is_err(),
        "truncating a file in a read-only preopen must be rejected"
    );
    if let Ok(fd) = result {
        // Defensively close the descriptor if the runtime handed one back so
        // that we can still verify the file was left untouched below.
        let _ = unsafe { wasip1::fd_close(fd) };
    }

    // Re-verify from within the guest that the file still contains its original
    // contents: the rejected truncation must not have modified anything.
    let file_fd = unsafe { wasip1::path_open(dir_fd, 0, FILENAME, 0, wasip1::RIGHTS_FD_READ, 0, 0) }
        .expect("opening the file for reading");
    let mut buffer = [0u8; 128];
    let nread = unsafe {
        wasip1::fd_read(
            file_fd,
            &[wasip1::Iovec {
                buf: buffer.as_mut_ptr(),
                buf_len: buffer.len(),
            }],
        )
    }
    .expect("reading file content");
    assert_eq!(
        &buffer[..nread],
        CONTENTS,
        "file contents must be unchanged after a rejected truncation"
    );

    unsafe { wasip1::fd_close(file_fd) }.expect("closing the file");
}

fn main() {
    // Open the read-only preopened directory by name.
    let dir_fd = match open_scratch_directory("readonly") {
        Ok(dir_fd) => dir_fd,
        Err(err) => {
            eprintln!("{err}");
            std::process::exit(1)
        }
    };

    test_readonly_truncation(dir_fd);
}
