use test_programs_artifacts::*;
use wasmtime::component::{Component, Linker as CLinker, ResourceTable};
use wasmtime::{Config, Engine, Linker, Module, Store};
use wasmtime_wasi::p1::{WasiP1Ctx, add_to_linker_async};
use wasmtime_wasi::p2::{IoView, WasiCtx, WasiCtxBuilder, WasiView, add_to_linker_async as p2_add};
use wasmtime_wasi::{DirPerms, FilePerms};

fn setup_dir() -> tempfile::TempDir {
    let td = tempfile::tempdir().unwrap();
    std::fs::create_dir(td.path().join("readonly")).unwrap();
    std::fs::write(
        td.path().join("readonly").join("test.txt"),
        b"truncation test file\n",
    )
    .unwrap();
    td
}

async fn run_p1() {
    let td = setup_dir();
    let engine = Engine::new(Config::new().async_support(true)).unwrap();
    let mut linker = Linker::<WasiP1Ctx>::new(&engine);
    add_to_linker_async(&mut linker, |t| t).unwrap();
    let mut builder = WasiCtxBuilder::new();
    builder.inherit_stdio();
    builder
        .preopened_dir(
            td.path().join("readonly"),
            "readonly",
            DirPerms::READ | DirPerms::MUTATE,
            FilePerms::READ,
        )
        .unwrap();
    let ctx = builder.build_p1();
    let mut store = Store::new(&engine, ctx);
    let module = Module::from_file(&engine, P1_FILE_TRUNCATION_READONLY).unwrap();
    let inst = linker.instantiate_async(&mut store, &module).await.unwrap();
    let start = inst.get_typed_func::<(), ()>(&mut store, "_start").unwrap();
    start.call_async(&mut store, ()).await.unwrap();
    let contents = std::fs::read(td.path().join("readonly").join("test.txt")).unwrap();
    assert_eq!(contents, b"truncation test file\n");
    println!("P1 OK: file unchanged");
}

struct P2Ctx {
    table: ResourceTable,
    wasi: WasiCtx,
}
impl IoView for P2Ctx {
    fn table(&mut self) -> &mut ResourceTable {
        &mut self.table
    }
}
impl WasiView for P2Ctx {
    fn ctx(&mut self) -> &mut WasiCtx {
        &mut self.wasi
    }
}

async fn run_p2() {
    let td = setup_dir();
    let engine = Engine::new(Config::new().async_support(true)).unwrap();
    let mut linker = CLinker::<P2Ctx>::new(&engine);
    p2_add(&mut linker).unwrap();
    let mut builder = WasiCtxBuilder::new();
    builder.inherit_stdio();
    builder
        .preopened_dir(
            td.path().join("readonly"),
            "readonly",
            DirPerms::READ | DirPerms::MUTATE,
            FilePerms::READ,
        )
        .unwrap();
    let ctx = P2Ctx {
        table: ResourceTable::new(),
        wasi: builder.build(),
    };
    let mut store = Store::new(&engine, ctx);
    let component = Component::from_file(&engine, P2_FILE_TRUNCATION_READONLY_COMPONENT).unwrap();
    let command =
        wasmtime_wasi::p2::bindings::Command::instantiate_async(&mut store, &component, &linker)
            .await
            .unwrap();
    command
        .wasi_cli_run()
        .call_run(&mut store)
        .await
        .unwrap()
        .unwrap();
    let contents = std::fs::read(td.path().join("readonly").join("test.txt")).unwrap();
    assert_eq!(contents, b"truncation test file\n");
    println!("P2 OK: file unchanged");
}

fn main() {
    let _ = Path::new("");
    let rt = tokio::runtime::Runtime::new().unwrap();
    rt.block_on(run_p1());
    rt.block_on(run_p2());
    println!("ALL OK");
}
